WITH base AS (WITH versions AS (SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'study_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM study_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'protocol_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM protocol_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'site_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM site_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'participant_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM participant_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'visit_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM visit_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'drug_kit_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM drug_kit_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'sample_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM sample_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'sample_shipment_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM sample_shipment_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'lab_test_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM lab_test_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'lab_result_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM lab_result_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'adverse_event_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM adverse_event_v UNION ALL SELECT record_id, logical_id, version_no, valid_from, recorded_at, change_kind, state_code, changed_by, related_refs_json, 'data_query_v' source_table, LAG(state_code) OVER(PARTITION BY logical_id ORDER BY version_no) prev_state FROM data_query_v), business AS (SELECT *, CASE state_code WHEN 'TV001' THEN 'Study Created' WHEN 'TV002' THEN 'Protocol Published' WHEN 'TV003' THEN 'Protocol Amended' WHEN 'TV004' THEN 'Site Initiated' WHEN 'TV005' THEN 'Site Suspended' WHEN 'TV006' THEN 'Site Reactivated' WHEN 'TV007' THEN 'Site Closed' WHEN 'TV008' THEN 'Participant Screened' WHEN 'TV009' THEN 'Screening Failed' WHEN 'TV010' THEN 'Consent Signed' WHEN 'TV011' THEN 'Consent Withdrawn' WHEN 'TV012' THEN 'Participant Reconsented' WHEN 'TV013' THEN 'Participant Enrolled' WHEN 'TV014' THEN 'Participant Randomized' WHEN 'TV015' THEN 'Participant Discontinued' WHEN 'TV016' THEN 'Participant Completed' WHEN 'TV017' THEN 'Visit Scheduled' WHEN 'TV018' THEN 'Visit Rescheduled' WHEN 'TV019' THEN 'Visit Started' WHEN 'TV020' THEN 'Visit Completed' WHEN 'TV021' THEN 'Visit Missed' WHEN 'TV022' THEN 'Visit Canceled' WHEN 'TV023' THEN 'Drug Kit Assigned' WHEN 'TV024' THEN 'Drug Kit Dispensed' WHEN 'TV025' THEN 'Dose Administered' WHEN 'TV026' THEN 'Dose Held' WHEN 'TV027' THEN 'Drug Kit Returned' WHEN 'TV028' THEN 'Sample Collection Ordered' WHEN 'TV029' THEN 'Sample Collected' WHEN 'TV030' THEN 'Sample Collection Canceled' WHEN 'TV031' THEN 'Sample Accessioned' WHEN 'TV032' THEN 'Aliquot Created' WHEN 'TV033' THEN 'Sample Frozen' WHEN 'TV034' THEN 'Sample Thawed' WHEN 'TV035' THEN 'Sample Destroyed' WHEN 'TV036' THEN 'Sample Shipment Created' WHEN 'TV037' THEN 'Sample Shipment Packed' WHEN 'TV038' THEN 'Sample Shipment Dispatched' WHEN 'TV039' THEN 'Sample Shipment Received' WHEN 'TV040' THEN 'Lab Test Ordered' WHEN 'TV041' THEN 'Lab Test Started' WHEN 'TV042' THEN 'Lab Test Completed' WHEN 'TV043' THEN 'Lab Test Repeated' WHEN 'TV044' THEN 'Result Entered' WHEN 'TV045' THEN 'Result Validated' WHEN 'TV046' THEN 'Result Amended' WHEN 'TV047' THEN 'Adverse Event Opened' WHEN 'TV048' THEN 'Adverse Event Graded' WHEN 'TV049' THEN 'Adverse Event Escalated' WHEN 'TV050' THEN 'Adverse Event Resolved' WHEN 'TV051' THEN 'Protocol Deviation Raised' WHEN 'TV052' THEN 'Protocol Deviation Waived' WHEN 'TV053' THEN 'Protocol Deviation Closed' WHEN 'TV054' THEN 'Data Query Opened' WHEN 'TV055' THEN 'Data Query Answered' WHEN 'TV056' THEN 'Data Query Closed' END activity FROM versions WHERE change_kind='BUSINESS') SELECT r.target_logical_id case_id, business.activity, business.valid_from timestamp, business.source_table, business.record_id source_record_id, business.changed_by actor, business.related_refs_json object_refs FROM business JOIN object_relation_v r ON r.source_logical_id=business.logical_id AND r.change_kind='BUSINESS' WHERE business.activity IS NOT NULL ORDER BY case_id, timestamp, source_record_id), selected AS (SELECT DISTINCT case_id FROM base WHERE json_array_length(object_refs)>=3) SELECT base.*,CASE WHEN json_array_length(object_refs)>=3 THEN 1 ELSE 0 END is_multi_object_event FROM base JOIN selected USING(case_id) ORDER BY case_id,timestamp,source_record_id;
